<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin']);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$keys=['hospital_name','hospital_email','hospital_phone','hospital_address','currency','default_language','timezone','date_format','time_format','appointment_duration','low_stock_threshold','session_timeout','github_repository','github_branch','ui_font_size','ui_accent','ui_sidebar_color','ui_page_color','ui_card_color'];foreach($keys as $k){$v=trim((string)($_POST[$k]??''));$q=$con->prepare('INSERT INTO system_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->bind_param('ss',$k,$v);$q->execute();}if(!empty($_FILES['logo']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['logo']['name'],PATHINFO_EXTENSION));if(in_array($ext,['png','jpg','jpeg','webp'],true)){@mkdir(__DIR__.'/professional_assets/uploads',0775,true);$fn='logo_'.time().'.'.$ext;move_uploaded_file($_FILES['logo']['tmp_name'],__DIR__.'/professional_assets/uploads/'.$fn);$path='professional_assets/uploads/'.$fn;$q=$con->prepare("UPDATE hospital_settings SET hospital_name=?,hospital_logo=?,currency=? WHERE setting_id=1");$hn=$_POST['hospital_name'];$cur=$_POST['currency'];$q->bind_param('sss',$hn,$path,$cur);$q->execute();}}$msg='Settings saved.';log_action($con,'Settings Updated','Hospital settings changed');}$vals=[];$r=$con->query('SELECT setting_key,setting_value FROM system_settings');while($x=$r->fetch_assoc())$vals[$x['setting_key']]=$x['setting_value'];$hs=$con->query('SELECT * FROM hospital_settings WHERE setting_id=1')->fetch_assoc();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Settings</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">ADMINISTRATION</span><h1>Professional Settings</h1><p>Hospital identity, regional settings, system rules and GitHub deployment information.</p></div></div><?php if($msg):?><div class="success"><?php echo esc($msg);?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="settings-grid"><div class="panel"><h2>Hospital identity</h2><label>Hospital name<input name="hospital_name" value="<?php echo esc($hs['hospital_name']??'Station Hospital');?>"></label><label>Email<input name="hospital_email" value="<?php echo esc($vals['hospital_email']??'');?>"></label><label>Phone<input name="hospital_phone" value="<?php echo esc($vals['hospital_phone']??'');?>"></label><label>Address<textarea name="hospital_address"><?php echo esc($vals['hospital_address']??'');?></textarea></label><label>Hospital logo<input type="file" name="logo" accept="image/*"></label></div><div class="panel"><h2>Language & regional</h2><label>Default language<select name="default_language"><option value="en" <?php echo ($vals['default_language']??'en')==='en'?'selected':'';?>>English</option><option value="ps" <?php echo ($vals['default_language']??'')==='ps'?'selected':'';?>>پښتو</option><option value="fa" <?php echo ($vals['default_language']??'')==='fa'?'selected':'';?>>دری</option></select></label><label>Timezone<input name="timezone" value="<?php echo esc($vals['timezone']??'Asia/Kabul');?>"></label><label>Currency<input name="currency" value="<?php echo esc($vals['currency']??'AFN');?>"></label><label>Date format<input name="date_format" value="<?php echo esc($vals['date_format']??'Y-m-d');?>"></label><label>Time format<input name="time_format" value="<?php echo esc($vals['time_format']??'H:i');?>"></label></div><div class="panel"><h2>Appearance</h2><label>Font size<input name="ui_font_size" type="number" min="12" max="20" value="<?php echo esc($vals['ui_font_size']??'16');?>"></label><label>Primary color<input name="ui_accent" type="color" value="<?php echo esc($vals['ui_accent']??'#2c78d4');?>"></label><label>Sidebar color<input name="ui_sidebar_color" type="color" value="<?php echo esc($vals['ui_sidebar_color']??'#10253f');?>"></label><label>Page background<input name="ui_page_color" type="color" value="<?php echo esc($vals['ui_page_color']??'#f4f7fb');?>"></label><label>Card color<input name="ui_card_color" type="color" value="<?php echo esc($vals['ui_card_color']??'#ffffff');?>"></label><p class="muted">These settings change the visual style across the hospital system.</p></div><div class="panel"><h2>Hospital operations</h2><label>Appointment duration (minutes)<input name="appointment_duration" type="number" value="<?php echo esc($vals['appointment_duration']??'30');?>"></label><label>Low stock threshold<input name="low_stock_threshold" type="number" value="<?php echo esc($vals['low_stock_threshold']??'10');?>"></label><label>Session timeout (minutes)<input name="session_timeout" type="number" value="<?php echo esc($vals['session_timeout']??'60');?>"></label></div><div class="panel"><h2>GitHub</h2><label>Repository URL<input name="github_repository" placeholder="https://github.com/yourname/hospital-system" value="<?php echo esc($vals['github_repository']??'');?>"></label><label>Branch<input name="github_branch" value="<?php echo esc($vals['github_branch']??'main');?>"></label><p class="muted">GitHub stores code, not your MySQL patient data. Always download a SQL backup before updating application code.</p></div></div><button class="primary-btn">Save All Settings</button></form></div></body></html>